// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;

    function setUp() public {
        c = new Synth(address(this), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address spender, uint256 initialAllowance, uint256 subtractedValue) public {
        vm.assume(spender != address(0));
        vm.assume(subtractedValue > 0);
        vm.assume(subtractedValue <= initialAllowance);
        vm.assume(initialAllowance < type(uint256).max);

        c.approve(spender, initialAllowance);

        uint256 beforeAllowance = c.allowance(address(this), spender);
        bool ok = c.decreaseAllowance(spender, subtractedValue);
        uint256 afterAllowance = c.allowance(address(this), spender);

        assertTrue(ok && afterAllowance == beforeAllowance - subtractedValue);
    }
}

